def clean(t):
 for src,ident in ids.items():t=t.replace('`'+src+'`','[['+ident+']]')
 t=t.replace('`five-dimensional-common-middle-trace-construction.md`', '[['+trade+']]').replace('`circles-in-four-dimensional-traces.md`','[['+circle+']]')
 t=t.replace('the actual n=5,k=2 handle slide','the actual $n=5,k=2$ handle slide')
 t=re.sub(r'\$\$(.*?)\$\$',lambda m:' $'+re.sub(r'\s+',' ',m.group(1)).strip()+'$ ',t,flags=re.S)
 t=re.sub(r'\\\[(.*?)\\\]',lambda m:' $'+re.sub(r'\s+',' ',m.group(1)).strip()+'$ ',t,flags=re.S)
 t=t.replace('`','')
 t=re.sub(r'^\*\s+', '',t,flags=re.M)
 return re.sub(r'\s+',' ',t).strip()

def phase_sections(text):
 hs=list(re.finditer(r'^(#{2,3})\s+([0-9]+(?:\.[0-9]+)?)[.]?\s+(.*)$',text,re.M))
 return [(m.group(2),m.group(3),text[m.end():hs[j+1].start() if j+1<len(hs) else len(text)]) for j,m in enumerate(hs)]

